#!/usr/bin/env python3
"""Generate approved-profile interface v1; --check verifies exact output."""
from pathlib import Path
import sys
TARGET=Path('Solidity/Backend/InternalFlow/RuntimeFrameV3ApprovedProfile.lean')
CONTENT="import Solidity.Backend.InternalFlow.RuntimeFrameInterfaceV3\nimport Solidity.Lowering.P8.ProducerAssembly\n\n/-! Approved-profile provenance interface, version 1. Generated by\nscripts/generate-runtime-frame-approved-profile.py. There is no producer\ninstance, default admission domain, execution oracle or new source semantics.\nThe source specification, origins, admission half and input correspondence\nmust be independently pinned to the original source/resource profile.\nExisting frozen V3 signatures are unchanged. -/\nnamespace Solidity.Backend.InternalFlow.RuntimeFrame.ApprovedProfile\nopen Evm Evm.Memory\nopen Solidity.Lowering.P8\n\n/-- An explicit external input-correspondence dependency. It relates the\nEXISTING source-origin program, exact artifact, environment and resource to the SAME intrinsic\ncaller, address map, machine, frame and quotation index used by V3. No value\nof this type is provided. Its actual-source adequacy remains a producer duty;\nit must not be chosen from an emitter's Entry, run or admission predicate. -/\nabbrev SourceInputs (S : P8a.Spec) (C : Contract) (Γ : Ctx) :=\n P8a.SourceProgram → Roadmap.Artifact → S.lang.Env → S.lang.Res →\n (index L frame : Nat) → State C Γ → (Nat → Fin W) → Machine → Nat → Prop\n\n/-- Exact image of the published admission half and independently supplied\nsource/runtime input relation. All and only such linked source cases are\nretained for the SAME supplied artifact; no existential artifact replacement\nis allowed. No NoFail, Forward-only, fixed-index or extra resource exclusion is\nintroduced. This definition alone proves no actual correspondence. -/\ndef sourceImage {C : Contract} {Γ : Ctx} {S : P8a.Spec} {roots : P8a.RootModel S}\n (admission : ProducerAssembly.AdmissionHalf S roots) (origins : P8a.SourceOrigins S)\n (artifact : Roadmap.Artifact) (inputs : SourceInputs S C Γ) (index : Nat) : InterfaceV3.Admission C Γ :=\n fun L frame caller base machine start =>\n   ∃ (input : S.Input) (resolved : S.Resolved) (well : S.WellFormed resolved)\n     (profile : S.InProfile resolved)\n     (environment : S.lang.Env) (resource : S.lang.Res),\n     admission.admission.frontend input = some resolved ∧\n     S.lang.Allowed environment ∧ S.lang.Admissible resource ∧\n     inputs (origins.meaning resolved well profile artifact) artifact environment resource\n       index L frame caller base machine start\n\n/-- Pending provenance and runtime agreement at a specified index. The\nexternal source inputs are parameters, not models selected by this record.\nInhabiting it does not supply a P8 realization, runtime frame producer or the\nactual-source adequacy of SourceInputs. All remain separate obligations. -/\nstructure Pending {C : Contract} {Γ : Ctx} {S : P8a.Spec} {roots : P8a.RootModel S}\n (admission : ProducerAssembly.AdmissionHalf S roots) (origins : P8a.SourceOrigins S)\n (artifact : Roadmap.Artifact) (inputs : SourceInputs S C Γ) (index : Nat)\n (approved admitted : InterfaceV3.Admission C Γ) where\n required_source : InterfaceV3.AdmissionAgreement approved (sourceImage admission origins artifact inputs index)\n required_agreement : InterfaceV3.AdmissionAgreement approved admitted\n\n/-- The same provenance/agreement duties at EVERY supplied index. This\nreuses V3's actual family agreement without replacing its coverage, code,\nsuccess/revert witnesses, source coherence or target execution claims. No\nrecord inhabitant or claim of full-profile coverage is provided. -/\nstructure PendingFamily {C : Contract} {Γ : Ctx} {S : P8a.Spec} {roots : P8a.RootModel S}\n (admission : ProducerAssembly.AdmissionHalf S roots) (origins : P8a.SourceOrigins S)\n (artifact : Roadmap.Artifact) (inputs : SourceInputs S C Γ)\n (approved admitted : Nat → InterfaceV3.Admission C Γ) where\n required_source : InterfaceV3.FamilyAdmissionAgreement approved (sourceImage admission origins artifact inputs)\n required_agreement : InterfaceV3.FamilyAdmissionAgreement approved admitted\n\nend Solidity.Backend.InternalFlow.RuntimeFrame.ApprovedProfile\n"
if sys.argv[1:]==['--check']:
 raise SystemExit(0 if TARGET.read_text()==CONTENT else 1)
if sys.argv[1:]:raise SystemExit('usage: generate-runtime-frame-approved-profile.py [--check]')
TARGET.write_text(CONTENT)
